var fileNode = $context.$nodes.READ_FILE_FROM_CHAT_INTERFACE;
var fileOutput = new Object();
if (fileNode && fileNode.$output) {
  fileOutput = fileNode.$output;
}

var asString = function(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
};

var upper = function(v) {
  return asString(v).toUpperCase();
};

var toArray = function(v) {
  if (Array.isArray(v)) return v;
  return [];
};

var firstNonBlank = function(vals) {
  for (var i = 0; i < vals.length; i++) {
    var v = vals[i];
    if (v !== null && v !== undefined && String(v).trim() !== '') return v;
  }
  return null;
};

var pushMissingOnce = function(arr, fieldName) {
  for (var i = 0; i < arr.length; i++) {
    if (arr[i] === fieldName) return;
  }
  arr.push(fieldName);
};

var textLooksLikeNoFile = function(text) {
  var s = asString(text).toLowerCase();
  if (!s) return false;
  if (s.indexOf('no file') >= 0) return true;
  if (s.indexOf('no uploaded') >= 0) return true;
  if (s.indexOf('file') >= 0 && s.indexOf('not') >= 0 && s.indexOf('uploaded') >= 0) return true;
  if (s.indexOf('file') >= 0 && s.indexOf('missing') >= 0) return true;
  return false;
};

var data = new Object();
if (fileOutput && (fileOutput.records || fileOutput.fileLevelErrors || fileOutput.recordCount !== undefined)) {
  data = fileOutput;
} else if (fileOutput && fileOutput.result && (fileOutput.result.records || fileOutput.result.fileLevelErrors || fileOutput.result.recordCount !== undefined)) {
  data = fileOutput.result;
} else if (fileOutput && fileOutput.output && (fileOutput.output.records || fileOutput.output.fileLevelErrors || fileOutput.output.recordCount !== undefined)) {
  data = fileOutput.output;
}

var records = toArray(data.records);
var fileLevelErrors = toArray(data.fileLevelErrors);
var output = new Object();
output.mode = 'NO_FILE';
output.hasFileRequest = false;
output.hasError = false;
output.message = null;
output.workflowRequest = null;
output.sourceFileName = firstNonBlank([data.sourceFileName, null]);
output.sheetName = firstNonBlank([data.sheetName, null]);
output.recordCount = records.length;
output.readyRecordCount = 0;
output.invalidRecordCount = 0;

for (var i = 0; i < records.length; i++) {
  var row = records[i] || new Object();
  var status = upper(row.rowStatus);
  if (status === 'READY') output.readyRecordCount = output.readyRecordCount + 1;
  if (status === 'INVALID') output.invalidRecordCount = output.invalidRecordCount + 1;
}

var noFileSignal = false;
for (var e = 0; e < fileLevelErrors.length; e++) {
  if (textLooksLikeNoFile(fileLevelErrors[e])) noFileSignal = true;
}

if (records.length === 0) {
  if (fileLevelErrors.length === 0 || noFileSignal === true) {
    output.mode = 'NO_FILE';
    return output;
  }
  output.mode = 'FILE_ERROR';
  output.hasError = true;
  output.message = 'I could not read a valid manager update row from the uploaded file. File level errors: ' + fileLevelErrors.join('; ');
  return output;
}

if (fileLevelErrors.length > 0 && noFileSignal === false) {
  output.mode = 'FILE_ERROR';
  output.hasError = true;
  output.message = 'I could not process the uploaded manager update file because: ' + fileLevelErrors.join('; ');
  return output;
}

if (records.length > 1) {
  output.mode = 'FILE_ERROR';
  output.hasError = true;
  output.message = 'The uploaded file contains ' + records.length + ' manager update rows. This workflow version processes one row per run so that each manager update can be reviewed and approved safely. Please upload a file with one manager update row.';
  return output;
}

var fileRow = records[0] || new Object();
var rowErrors = toArray(fileRow.rowValidationErrors).slice(0);
var missingFields = toArray(fileRow.missingFields).slice(0);

var workerPersonNumber = firstNonBlank([fileRow.personNumber, null]);
var workerName = firstNonBlank([fileRow.personName, null]);
var newManagerPersonNumber = firstNonBlank([fileRow.newManagerPersonNumber, null]);
var newManagerName = firstNonBlank([fileRow.newManagerPersonName, null]);
var workerLookup = firstNonBlank([fileRow.workerLookupValue, workerPersonNumber, workerName]);
var managerLookup = firstNonBlank([fileRow.newManagerLookupValue, newManagerPersonNumber, newManagerName]);
var effectiveDate = firstNonBlank([fileRow.effectiveDate, null]);
var updateType = firstNonBlank([fileRow.updateType, null]);

if (!workerLookup) pushMissingOnce(missingFields, 'personNumberOrName');
if (!managerLookup) pushMissingOnce(missingFields, 'newManagerPersonNumberOrName');
if (!effectiveDate) pushMissingOnce(missingFields, 'effectiveDate');
if (!(updateType === 'LINE_MANAGER' || updateType === 'HS2_TIMECARD_MANAGER')) pushMissingOnce(missingFields, 'updateType');

if (upper(fileRow.rowStatus) !== 'READY') {
  if (rowErrors.length === 0) rowErrors.push('The file row was not marked as READY by the file processor.');
}

if (missingFields.length > 0 || rowErrors.length > 0) {
  output.mode = 'FILE_ERROR';
  output.hasError = true;
  var rowNumberText = fileRow.rowNumber ? String(fileRow.rowNumber) : 'unknown';
  var parts = [];
  parts.push('The uploaded manager update row is not ready for processing. Row: ' + rowNumberText + '.');
  if (missingFields.length > 0) parts.push('Missing fields: ' + missingFields.join(', ') + '.');
  if (rowErrors.length > 0) parts.push('Row errors: ' + rowErrors.join('; '));
  output.message = parts.join(' ');
  return output;
}

var normalizedRequest = new Object();
normalizedRequest.intent = 'manager_update';
normalizedRequest.inputSource = 'FILE';
normalizedRequest.sourceFileName = firstNonBlank([data.sourceFileName, null]);
normalizedRequest.sourceSheetName = firstNonBlank([data.sheetName, null]);
normalizedRequest.sourceRowNumber = fileRow.rowNumber || null;
normalizedRequest.sourceRecordCount = records.length;
normalizedRequest.updateType = updateType;
normalizedRequest.workerPersonNumber = workerPersonNumber;
normalizedRequest.workerName = workerName;
normalizedRequest.workerLookupValue = workerLookup;
normalizedRequest.newManagerPersonNumber = newManagerPersonNumber;
normalizedRequest.newManagerName = newManagerName;
normalizedRequest.newManagerLookupValue = managerLookup;
normalizedRequest.effectiveDate = effectiveDate;
normalizedRequest.reasonCode = null;
normalizedRequest.readyToProceed = true;
normalizedRequest.missingFields = [];
normalizedRequest.crossQuestion = null;
normalizedRequest.summary = updateType + ' update from uploaded file for worker ' + workerLookup + ' effective ' + effectiveDate + '.';

output.mode = 'FILE_READY';
output.hasFileRequest = true;
output.hasError = false;
output.message = null;
output.workflowRequest = normalizedRequest;
return output;

var req = new Object();
if ($context.$variables && $context.$variables.vManagerUpdateRequest) {
  req = $context.$variables.vManagerUpdateRequest;
}

var asString = (v) => {
  if (v === null || v === undefined) return '';
  return String(v).trim();
};

var firstNonBlank = (vals) => {
  for (var i = 0; i < vals.length; i++) {
    var v = vals[i];
    if (v !== null && v !== undefined && String(v).trim() !== '') return v;
  }
  return null;
};

var escapeQueryLiteral = (v) => {
  return asString(v).split("'").join("''");
};

var hasAnyWhitespace = (s) => {
  var text = asString(s);
  for (var i = 0; i < text.length; i++) {
    var c = text.charCodeAt(i);
    if (c === 9 || c === 10 || c === 11 || c === 12 || c === 13 || c === 32) return true;
  }
  return false;
};

var hasAnyDigit = (s) => {
  var text = asString(s);
  for (var i = 0; i < text.length; i++) {
    var c = text.charCodeAt(i);
    if (c >= 48 && c <= 57) return true;
  }
  return false;
};

var makeLookupResult = (query, mode, input) => {
  var result = new Object();
  result.query = query;
  result.mode = mode;
  result.input = input;
  return result;
};

var buildWorkerQuery = (inputValue) => {
  var raw = asString(inputValue);
  if (!raw) {
    return makeLookupResult(null, 'MISSING', raw);
  }
  var escaped = escapeQueryLiteral(raw);
  var personNumberLike = (!hasAnyWhitespace(raw) && hasAnyDigit(raw));
  if (personNumberLike) {
    return makeLookupResult("PersonNumber='" + escaped + "'", 'PERSON_NUMBER', raw);
  }
  return makeLookupResult("UPPER(DisplayName)=UPPER('" + escaped + "')", 'DISPLAY_NAME', raw);
};

// Manual requests still use workerPersonNumber and newManagerPersonNumber.
// File-based requests use workerLookupValue and newManagerLookupValue so names are not stored in person-number fields.
var targetInput = firstNonBlank([req.workerLookupValue, req.workerPersonNumber, req.workerName]);
var managerInput = firstNonBlank([req.newManagerLookupValue, req.newManagerPersonNumber, req.newManagerName]);

var target = buildWorkerQuery(targetInput);
var manager = buildWorkerQuery(managerInput);
var errors = [];
if (!target.query) errors.push('Worker name or number is required.');
if (!manager.query) errors.push('Proposed manager name or number is required.');

var output = new Object();
output.hasError = errors.length > 0;
output.errors = errors;
output.targetWorkerQuery = target.query;
output.targetLookupMode = target.mode;
output.targetLookupText = target.input;
output.newManagerQuery = manager.query;
output.newManagerLookupMode = manager.mode;
output.newManagerLookupText = manager.input;
return output;

const req = ($context.$variables && $context.$variables.vManagerUpdateRequest) ? $context.$variables.vManagerUpdateRequest : ($context.$nodes.PARSE_MANAGER_UPDATE_REQUEST.$output || {});
const targetResponse = $context.$nodes.GET_TARGET_WORKER.$output || {};
const newMgrResponse = $context.$nodes.GET_NEW_MANAGER.$output || {};
const lookupDate = $context.$system.$currentDate;
const updateDate = req.effectiveDate;
const lookupCtx = ($context.$nodes.BUILD_WORKER_LOOKUP_QUERIES_SAFE_V3 && $context.$nodes.BUILD_WORKER_LOOKUP_QUERIES_SAFE_V3.$output && $context.$nodes.BUILD_WORKER_LOOKUP_QUERIES_SAFE_V3.$output.result) ? $context.$nodes.BUILD_WORKER_LOOKUP_QUERIES_SAFE_V3.$output.result : {};

const itemsOf = (response) => {
  if (!response) return [];
  if (Array.isArray(response.items)) return response.items;
  if (Array.isArray(response.Items)) return response.Items;
  return [];
};

const childItems = (obj, prop) => {
  if (!obj) return [];
  const v = obj[prop];
  if (Array.isArray(v)) return v;
  if (v && Array.isArray(v.items)) return v.items;
  if (v && Array.isArray(v.Items)) return v.Items;
  return [];
};

const firstNonBlank = (vals) => {
  for (let i = 0; i < vals.length; i++) {
    const v = vals[i];
    if (v !== null && v !== undefined && String(v).trim() !== '') return v;
  }
  return null;
};

const upper = (v) => String(v === null || v === undefined ? '' : v).trim().toUpperCase();

const asString = (v) => (v === null || v === undefined) ? '' : String(v).trim();

const displayNameFromNameItem = (n) => {
  if (!n) return null;
  const fullFromParts = firstNonBlank([
    n.FullName,
    n.DisplayName,
    n.ListName,
    n.Name,
    (firstNonBlank([n.FirstName, n.GivenName]) && firstNonBlank([n.LastName, n.FamilyName])) ? (firstNonBlank([n.FirstName, n.GivenName]) + ' ' + firstNonBlank([n.LastName, n.FamilyName])) : null
  ]);
  return fullFromParts;
};

const displayName = (person) => {
  if (!person) return null;
  const names = childItems(person, 'names');
  let primaryName = null;
  let globalName = null;
  let anyName = null;
  for (let i = 0; i < names.length; i++) {
    const n = names[i] || {};
    const dn = displayNameFromNameItem(n);
    if (!dn) continue;
    if (!anyName) anyName = dn;
    if (!primaryName && (n.PrimaryFlag === true || upper(n.PrimaryFlag) === 'TRUE' || upper(n.PrimaryFlag) === 'Y')) primaryName = dn;
    if (!globalName && (upper(n.NameType) === 'GLOBAL' || upper(n.NameType) === 'GLOBAL_NAME')) globalName = dn;
  }
  return firstNonBlank([
    person.DisplayName,
    person.displayName,
    person.PersonDisplayName,
    person.FullName,
    person.Name,
    person.PersonName,
    primaryName,
    globalName,
    anyName,
    person.PersonNumber
  ]);
};

const personNumberFromAssignmentNumber = (assignmentNumber) => {
  const s = asString(assignmentNumber);
  if (!s) return null;
  const m = /(\d+)$/.exec(s);
  return m ? m[1] : null;
};

const directLinksOf = (item) => {
  if (!item) return [];
  let links = [];
  if (Array.isArray(item.links)) links = links.concat(item.links);
  if (Array.isArray(item.Links)) links = links.concat(item.Links);
  return links;
};

const contextLinksOf = (item) => {
  if (!item) return [];
  let links = [];
  const c = item['@context'] || item.context || item.Context || null;
  if (c && Array.isArray(c.links)) links = links.concat(c.links);
  if (c && Array.isArray(c.Links)) links = links.concat(c.Links);
  return links;
};

const keyLooksLikeOpaqueHrefKey = (key) => {
  const k = asString(key);
  if (!k) return false;
  if (k.indexOf(',') >= 0 || k.indexOf('%2C') >= 0 || k.indexOf('%2c') >= 0) return false;
  if (/^\d+$/.test(k)) return false;
  // Oracle opaque REST keys from the raw href are long hexadecimal hash-like values.
  return /^[0-9A-Fa-f]{40,}$/.test(k);
};

const leftPad = (text, length, padChar) => {
  let s = asString(text);
  const p = asString(padChar) || '0';
  while (s.length < length) s = p + s;
  return s;
};

const numericIdFromEffectiveDatedKey = (key) => {
  const k = asString(key);
  if (!k) return null;
  const decoded = k.replace(/%2C/gi, ',');
  const first = decoded.split(',')[0];
  if (/^\d+$/.test(first)) return first;
  return null;
};

const dateToUtcMidnightMillisHex = (dateText) => {
  const d = asString(dateText);
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(d);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const day = Number(m[3]);
  const millis = Date.UTC(y, mo - 1, day);
  if (!isFinite(millis)) return null;
  return leftPad(millis.toString(16).toUpperCase(), 16, '0');
};

const oracleOpaqueKeyFromIdAndDate = (numericId, dateText) => {
  const idText = asString(numericId);
  if (!/^\d+$/.test(idText)) return null;
  const idNumber = Number(idText);
  if (!isFinite(idNumber)) return null;
  const idHex = leftPad(idNumber.toString(16).toUpperCase(), 13, '0');
  const dateHex = dateToUtcMidnightMillisHex(dateText);
  if (!dateHex) return null;
  // This is the same serialized ADF key pattern observed in the raw workers, assignments, and managers hrefs.
  return '00020000000EACED00057708000' +
    idHex +
    '0000004AACED00057372000D6A6176612E73716C2E4461746514FA46683F3566970200007872000E6A6176612E7574696C2E44617465686A81014B59741903000078707708' +
    dateHex +
    '78';
};

const resolveOpaqueKey = (rawKey, numericId, lookupDateForKey, label, warnings) => {
  if (keyLooksLikeOpaqueHrefKey(rawKey)) {
    return { key: rawKey, source: 'raw_href', rawKey: rawKey };
  }
  const idCandidate = firstNonBlank([numericId, numericIdFromEffectiveDatedKey(rawKey)]);
  const generated = oracleOpaqueKeyFromIdAndDate(idCandidate, lookupDateForKey);
  if (generated && keyLooksLikeOpaqueHrefKey(generated)) {
    warnings.push(label + ' REST key was generated from numeric ID ' + idCandidate + ' and lookup effective date ' + lookupDateForKey + ' because Agent Studio returned a transformed effective-dated key instead of the raw href key.');
    return { key: generated, source: 'generated_from_numeric_id_and_lookup_date', rawKey: rawKey };
  }
  return { key: rawKey, source: rawKey ? 'unusable_transformed_key' : 'not_found', rawKey: rawKey };
};

const keyAfterSegment = (href, segment) => {
  if (!href || !segment) return null;
  const marker = '/' + segment + '/';
  const text = String(href);
  const idx = text.indexOf(marker);
  if (idx < 0) return null;
  const rest = text.substring(idx + marker.length);
  const key = rest.split('/')[0].split('?')[0];
  return key || null;
};

const keyFromLinks = (links, segment, expectedName) => {
  let fallback = null;
  for (let i = 0; i < links.length; i++) {
    const l = links[i] || {};
    if (!l.href) continue;
    const name = asString(l.name);
    if (expectedName && name && name !== expectedName) continue;
    const rel = asString(l.rel).toLowerCase();
    const key = keyAfterSegment(l.href, segment);
    if (!key) continue;
    if ((rel === 'self' || rel === 'canonical') && keyLooksLikeOpaqueHrefKey(key)) return key;
    if (!fallback) fallback = key;
  }
  for (let i = 0; i < links.length; i++) {
    const l = links[i] || {};
    if (!l.href) continue;
    const key = keyAfterSegment(l.href, segment);
    if (keyLooksLikeOpaqueHrefKey(key)) return key;
  }
  return fallback;
};

const keyFromItem = (item, segment, expectedName) => {
  // Prefer raw REST payload links. Agent Studio @context links can contain numeric effective-dated keys
  // such as 300000...%2C2026-06-02, and those keys caused the 404 in this instance.
  const directKey = keyFromLinks(directLinksOf(item), segment, expectedName);
  if (keyLooksLikeOpaqueHrefKey(directKey)) return directKey;
  const contextKey = keyFromLinks(contextLinksOf(item), segment, expectedName);
  if (keyLooksLikeOpaqueHrefKey(contextKey)) return contextKey;
  return directKey || contextKey;
};

const isNumericOnly = (v) => /^\d+$/.test(asString(v));

const isDateInRange = (date, start, end) => {
  const d = asString(date);
  const s = asString(start);
  const e = asString(end);
  if (!d) return true;
  if (s && d < s) return false;
  if (e && d > e) return false;
  return true;
};

const workRelIsActive = (rel, asOfDate) => {
  if (!rel) return false;
  const start = firstNonBlank([rel.StartDate, rel.EffectiveStartDate]);
  const end = firstNonBlank([rel.TerminationDate, rel.ProjectedTerminationDate, rel.EffectiveEndDate, '4712-12-31']);
  return isDateInRange(asOfDate, start, end);
};

const workRelIsPrimary = (rel) => {
  return rel && (rel.PrimaryFlag === true || upper(rel.PrimaryFlag) === 'TRUE' || upper(rel.PrimaryFlag) === 'Y');
};

const assignmentIsPrimary = (a) => {
  return a && (
    a.PrimaryAssignmentFlag === true ||
    a.AssignmentPrimaryFlag === true ||
    a.PrimaryFlag === true ||
    upper(a.PrimaryAssignmentFlag) === 'TRUE' ||
    upper(a.AssignmentPrimaryFlag) === 'TRUE' ||
    upper(a.PrimaryFlag) === 'TRUE' ||
    upper(a.PrimaryAssignmentFlag) === 'Y' ||
    upper(a.PrimaryFlag) === 'Y'
  );
};

const assignmentIsActive = (a, asOfDate) => {
  if (!a) return false;
  const status = upper(firstNonBlank([a.AssignmentStatusType, a.AssignmentStatusTypeCode, a.AssignmentStatus, a.AssignmentStatusMeaning]));
  const statusActive = !status || status.indexOf('ACTIVE') >= 0 || status === 'ACT';
  const inRange = isDateInRange(asOfDate, a.EffectiveStartDate, firstNonBlank([a.EffectiveEndDate, '4712-12-31']));
  const latest = !a.EffectiveLatestChange || upper(a.EffectiveLatestChange) === 'Y' || upper(a.EffectiveLatestChange) === 'TRUE';
  return statusActive && inRange && latest;
};

const chooseWorkRelationship = (worker, asOfDate, errors, label) => {
  const rels = childItems(worker, 'workRelationships');
  if (!rels.length) return null;
  const active = [];
  for (let i = 0; i < rels.length; i++) {
    if (workRelIsActive(rels[i], asOfDate)) active.push(rels[i]);
  }
  const candidates = active.length ? active : rels;
  const primaryActive = [];
  for (let i = 0; i < candidates.length; i++) {
    if (workRelIsPrimary(candidates[i])) primaryActive.push(candidates[i]);
  }
  if (primaryActive.length === 1) return primaryActive[0];
  if (active.length === 1) return active[0];
  if (primaryActive.length > 1) errors.push('More than one active primary work relationship was found for ' + label + '. Please resolve the duplicate work relationship before using the agent.');
  else if (active.length > 1) errors.push('More than one active work relationship was found for ' + label + '. Please resolve the duplicate work relationship before using the agent.');
  return candidates[0];
};

const chooseAssignment = (rel, asOfDate, errors, label) => {
  const assignments = childItems(rel, 'assignments');
  if (!assignments.length) return null;
  const activePrimary = [];
  const primary = [];
  const active = [];
  for (let i = 0; i < assignments.length; i++) {
    if (assignmentIsPrimary(assignments[i])) primary.push(assignments[i]);
    if (assignmentIsActive(assignments[i], asOfDate)) active.push(assignments[i]);
    if (assignmentIsPrimary(assignments[i]) && assignmentIsActive(assignments[i], asOfDate)) activePrimary.push(assignments[i]);
  }
  if (activePrimary.length === 1) return activePrimary[0];
  if (activePrimary.length > 1) errors.push('More than one active primary assignment was found for ' + label + '. Please resolve the duplicate assignment before using the agent.');
  if (primary.length === 1) return primary[0];
  if (active.length === 1) return active[0];
  if (active.length > 1) errors.push('More than one active assignment was found for ' + label + '. Please resolve the duplicate assignment before using the agent.');
  return assignments[0];
};

const managerDisplay = (mgr) => {
  return firstNonBlank([
    mgr && mgr.ManagerName,
    mgr && mgr.ManagerDisplayName,
    mgr && mgr.DisplayName,
    mgr && mgr.ManagerPersonName,
    mgr && mgr.ManagerPersonNumber,
    mgr && mgr.ManagerAssignmentNumber,
    'Not currently assigned'
  ]);
};

const managerOverlapsDate = (mgr, date) => {
  if (!mgr) return false;
  return isDateInRange(date, mgr.EffectiveStartDate, firstNonBlank([mgr.EffectiveEndDate, '4712-12-31']));
};

const managersForType = (assign, managerType) => {
  const managers = childItems(assign, 'managers');
  const matches = [];
  for (let i = 0; i < managers.length; i++) {
    if (upper(managers[i] && managers[i].ManagerType) === managerType) matches.push(managers[i]);
  }
  return matches;
};

const activeManagersForType = (assign, managerType, date) => {
  const matches = managersForType(assign, managerType);
  const active = [];
  for (let i = 0; i < matches.length; i++) {
    if (managerOverlapsDate(matches[i], date)) active.push(matches[i]);
  }
  return active;
};

const recordForManager = (assign, managerType, date, errors) => {
  const matches = managersForType(assign, managerType);
  const active = activeManagersForType(assign, managerType, date);
  if (active.length > 1) {
    errors.push('Duplicate active ' + managerType + ' records were found for the active primary assignment on ' + date + '. Please correct the duplicate manager rows before using the agent.');
  }
  const mgr = active.length ? active[0] : (matches.length === 1 ? matches[0] : null);
  if (matches.length > 1 && active.length === 0) {
    errors.push('Multiple ' + managerType + ' records were found, but none is active for ' + date + '. Please review the manager date ranges before using the agent.');
  }
  const rawManagersUniqID = mgr ? keyFromItem(mgr, 'managers', 'managers') : null;
  const managerIdForKey = mgr ? firstNonBlank([mgr.AssignmentSupervisorId, mgr.assignmentSupervisorId, numericIdFromEffectiveDatedKey(rawManagersUniqID)]) : null;
  const managerKeyResolution = mgr ? resolveOpaqueKey(rawManagersUniqID, managerIdForKey, lookupDate, managerType + ' manager', warnings) : { key: null, source: 'not_found', rawKey: null };
  const managersUniqID = managerKeyResolution.key;
  const currentManagerAssignmentNumber = mgr ? firstNonBlank([mgr.ManagerAssignmentNumber, mgr.managerAssignmentNumber]) : null;
  const currentManagerPersonNumber = personNumberFromAssignmentNumber(currentManagerAssignmentNumber);
  return {
    exists: !!mgr,
    activeOnEffectiveDate: !!(mgr && managerOverlapsDate(mgr, date)),
    managerRecordCount: matches.length,
    activeRecordCount: active.length,
    managersUniqID: managersUniqID,
    rawManagersUniqID: rawManagersUniqID,
    managersUniqIDSource: managerKeyResolution.source,
    currentManager: mgr ? managerDisplay(mgr) : 'Not currently assigned',
    currentManagerAssignmentNumber: currentManagerAssignmentNumber,
    currentManagerPersonNumber: currentManagerPersonNumber,
    managerTypeMeaning: mgr ? firstNonBlank([mgr.ManagerTypeMeaning, mgr.ManagerType, managerType]) : managerType,
    effectiveStartDate: mgr ? mgr.EffectiveStartDate : null,
    effectiveEndDate: mgr ? mgr.EffectiveEndDate : null
  };
};

const buildPayload = (managerType, mode, assignmentId, assignmentNumber, reasonCode) => {
  const p = {
    ActionCode: 'MANAGER_CHANGE',
    ManagerAssignmentNumber: assignmentNumber,
    ManagerType: managerType
  };
