const newMgrItems = itemsOf(newMgrResponse);
const errors = [];
const warnings = [];

const lookupLabel = (person) => {
  if (!person) return 'Name not available | Person Number: Not available';
  const pn = firstNonBlank([person.PersonNumber, person.personNumber, 'Not available']);
  const dn = displayName(person) || 'Name not available';
  return dn + ' | Person Number: ' + pn;
};

const duplicateListText = (items) => {
  const rows = [];
  for (let i = 0; i < items.length; i++) rows.push(lookupLabel(items[i]));
  return rows.join('; ');
};

if (lookupCtx.hasError === true && lookupCtx.errors && lookupCtx.errors.length) {
  for (let i = 0; i < lookupCtx.errors.length; i++) errors.push(lookupCtx.errors[i]);
}

if (lookupCtx.targetLookupMode === 'DISPLAY_NAME' && targetItems.length > 1) {
  errors.push('Multiple workers were found for display name ' + lookupCtx.targetLookupText + '. Please rerun the request using the correct worker person number. Matches: ' + duplicateListText(targetItems));
}
if (lookupCtx.newManagerLookupMode === 'DISPLAY_NAME' && newMgrItems.length > 1) {
  errors.push('Multiple proposed managers were found for display name ' + lookupCtx.newManagerLookupText + '. Please rerun the request using the correct proposed manager person number. Matches: ' + duplicateListText(newMgrItems));
}

const targetWorker = targetItems.length ? targetItems[0] : null;
const newManagerWorker = newMgrItems.length ? newMgrItems[0] : null;

const resolvedTargetPersonNumber = targetWorker ? firstNonBlank([targetWorker.PersonNumber, targetWorker.personNumber]) : null;
const resolvedNewManagerPersonNumber = newManagerWorker ? firstNonBlank([newManagerWorker.PersonNumber, newManagerWorker.personNumber]) : null;
const resolvedTargetPersonId = targetWorker ? firstNonBlank([targetWorker.PersonId, targetWorker.personId]) : null;
const resolvedNewManagerPersonId = newManagerWorker ? firstNonBlank([newManagerWorker.PersonId, newManagerWorker.personId]) : null;
const resolvedTargetDisplayName = displayName(targetWorker);
const resolvedNewManagerDisplayName = displayName(newManagerWorker);

const normalizeNameForCompare = (v) => {
  return asString(v).toUpperCase().replace(/[^A-Z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
};

const nameLooksAligned = (providedName, resolvedName) => {
  const p = normalizeNameForCompare(providedName);
  const r = normalizeNameForCompare(resolvedName);
  if (!p || !r) return true;
  if (p === r) return true;
  if (p.indexOf(r) >= 0 || r.indexOf(p) >= 0) return true;
  const tokens = p.split(' ');
  let matched = 0;
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t && r.indexOf(t) >= 0) matched += 1;
  }
  if (tokens.length >= 2 && matched >= 2) return true;
  return tokens.length === 1 && matched === 1;
};


if (!targetWorker) errors.push('Target worker was not found for ' + (lookupCtx.targetLookupText || req.workerPersonNumber) + '.');
if (!newManagerWorker) errors.push('New manager was not found for ' + (lookupCtx.newManagerLookupText || req.newManagerPersonNumber) + '.');

if (targetWorker && req.workerPersonNumber && req.workerName && !nameLooksAligned(req.workerName, resolvedTargetDisplayName)) {
  errors.push('The uploaded worker person number ' + req.workerPersonNumber + ' resolved to ' + (resolvedTargetDisplayName || 'name not available') + ', but the uploaded file has worker name ' + req.workerName + '. Please correct the file before submitting the manager update.');
}
if (newManagerWorker && req.newManagerPersonNumber && req.newManagerName && !nameLooksAligned(req.newManagerName, resolvedNewManagerDisplayName)) {
  errors.push('The uploaded proposed manager person number ' + req.newManagerPersonNumber + ' resolved to ' + (resolvedNewManagerDisplayName || 'name not available') + ', but the uploaded file has proposed manager name ' + req.newManagerName + '. Please correct the file before submitting the manager update.');
}
if (targetWorker && newManagerWorker) {
  const sameResolvedPersonNumber = resolvedTargetPersonNumber && resolvedNewManagerPersonNumber && resolvedTargetPersonNumber === resolvedNewManagerPersonNumber;
  const sameResolvedPersonId = resolvedTargetPersonId && resolvedNewManagerPersonId && resolvedTargetPersonId === resolvedNewManagerPersonId;
  if (sameResolvedPersonNumber || sameResolvedPersonId) {
    errors.push('The target worker and proposed manager resolve to the same person. A worker cannot be assigned as their own manager.');
  }
}

let targetRel = null;
let targetAssign = null;
let newMgrRel = null;
let newMgrAssign = null;

if (targetWorker) {
  targetRel = chooseWorkRelationship(targetWorker, lookupDate, errors, 'target worker ' + (lookupCtx.targetLookupText || req.workerPersonNumber));
  if (!targetRel) errors.push('No work relationship was found for the target worker.');
  targetAssign = chooseAssignment(targetRel, lookupDate, errors, 'target worker ' + (lookupCtx.targetLookupText || req.workerPersonNumber));
  if (!targetAssign) errors.push('No active primary assignment was found for the target worker.');
}

if (newManagerWorker) {
  newMgrRel = chooseWorkRelationship(newManagerWorker, lookupDate, errors, 'new manager ' + (lookupCtx.newManagerLookupText || req.newManagerPersonNumber));
  newMgrAssign = chooseAssignment(newMgrRel, lookupDate, errors, 'new manager ' + (lookupCtx.newManagerLookupText || req.newManagerPersonNumber));
  if (!newMgrAssign) errors.push('No active primary assignment was found for the new manager.');
}

const rawWorkersUniqID = targetWorker ? keyFromItem(targetWorker, 'workers', 'workers') : null;
const targetWorkerIdForKey = targetWorker ? firstNonBlank([targetWorker.PersonId, targetWorker.personId, numericIdFromEffectiveDatedKey(rawWorkersUniqID)]) : null;
const workerKeyResolution = targetWorker ? resolveOpaqueKey(rawWorkersUniqID, targetWorkerIdForKey, lookupDate, 'Worker', warnings) : { key: null, source: 'not_found', rawKey: null };
const workersUniqID = workerKeyResolution.key;
const periodOfServiceId = firstNonBlank([targetRel && targetRel.PeriodOfServiceId, targetRel && targetRel.periodOfServiceId]);

const targetAssignmentId = firstNonBlank([targetAssign && targetAssign.AssignmentId, targetAssign && targetAssign.assignmentId]);
const rawAssignmentsUniqID = targetAssign ? keyFromItem(targetAssign, 'assignments', 'assignments') : null;
const assignmentIdForKey = firstNonBlank([targetAssignmentId, numericIdFromEffectiveDatedKey(rawAssignmentsUniqID)]);
const assignmentKeyResolution = targetAssign ? resolveOpaqueKey(rawAssignmentsUniqID, assignmentIdForKey, lookupDate, 'Assignment', warnings) : { key: null, source: 'not_found', rawKey: null };
const assignmentsUniqID = assignmentKeyResolution.key;
const targetAssignmentNumber = firstNonBlank([targetAssign && targetAssign.AssignmentNumber, targetAssign && targetAssign.AssignmentName]);
const newManagerAssignmentId = firstNonBlank([newMgrAssign && newMgrAssign.AssignmentId, newMgrAssign && newMgrAssign.assignmentId]);
const newManagerAssignmentNumber = firstNonBlank([newMgrAssign && newMgrAssign.AssignmentNumber, newMgrAssign && newMgrAssign.assignmentNumber, newMgrAssign && newMgrAssign.AssignmentName]);

if (!workersUniqID) errors.push('The workersUniqID could not be resolved from the worker self link named workers.');
if (workersUniqID && !keyLooksLikeOpaqueHrefKey(workersUniqID)) errors.push('The workersUniqID resolved to ' + workersUniqID + ', which is not usable. The agent could not generate an opaque REST key from PersonId ' + targetWorkerIdForKey + ' and lookup effective date ' + lookupDate + '.');
if (!periodOfServiceId) errors.push('The PeriodOfServiceId could not be resolved from the active work relationship.');
if (!assignmentsUniqID) errors.push('The assignmentsUniqID could not be resolved from the active primary assignment self link named assignments.');
if (assignmentsUniqID && !keyLooksLikeOpaqueHrefKey(assignmentsUniqID)) errors.push('The assignmentsUniqID resolved to ' + assignmentsUniqID + ', which is not usable. The agent could not generate an opaque REST key from AssignmentId ' + assignmentIdForKey + ' and lookup effective date ' + lookupDate + '.');
if (!newManagerAssignmentNumber) errors.push('The new manager assignment number could not be resolved from the new manager active primary assignment.');

const requestedManagerTypes = req.updateType === 'LINE_MANAGER' ? ['LINE_MANAGER', 'HS2_HS2_REWARD_MANAGER'] : ['HS2_TIMECARD_MANAGER'];
const managerRecords = {};
const payloads = {};
const updateItems = [];
const skippedItems = [];

if (targetAssign && newManagerAssignmentNumber) {
  for (let i = 0; i < requestedManagerTypes.length; i++) {
    const mt = requestedManagerTypes[i];
    const rec = recordForManager(targetAssign, mt, updateDate, errors);
    managerRecords[mt] = rec;
    payloads[mt] = {
      patchPayload: buildPayload(mt, 'patch', newManagerAssignmentId, newManagerAssignmentNumber, req.reasonCode),
      createPayload: buildPayload(mt, 'create', newManagerAssignmentId, newManagerAssignmentNumber, req.reasonCode)
    };

    if (rec.exists && !rec.managersUniqID) errors.push('The existing ' + mt + ' record was found, but the manager REST key could not be resolved from its self link.');
    if (rec.exists && rec.managersUniqID && !keyLooksLikeOpaqueHrefKey(rec.managersUniqID)) errors.push('The existing ' + mt + ' manager key resolved to ' + rec.managersUniqID + ', which is not usable. The agent could not generate an opaque manager key from AssignmentSupervisorId and lookup effective date ' + lookupDate + '.');
    if (rec.exists && !rec.activeOnEffectiveDate) errors.push('The existing ' + mt + ' record is not active on the requested effective date ' + updateDate + '. Current date range is ' + (rec.effectiveStartDate || 'unknown') + ' to ' + (rec.effectiveEndDate || 'unknown') + '.');

    const shouldExecute = mt === 'LINE_MANAGER' || mt === 'HS2_TIMECARD_MANAGER' || (mt === 'HS2_HS2_REWARD_MANAGER' && rec.exists === true);
    if (shouldExecute) {
      updateItems.push({
        managerType: mt,
        operation: rec.exists ? 'UPDATE' : 'CREATE',
        currentManager: rec.currentManager,
        currentManagerAssignmentNumber: rec.currentManagerAssignmentNumber,
        currentManagerPersonNumber: rec.currentManagerPersonNumber,
        currentEffectiveStartDate: rec.effectiveStartDate,
        currentEffectiveEndDate: rec.effectiveEndDate,
        newManager: displayName(newManagerWorker),
        newManagerPersonNumber: firstNonBlank([resolvedNewManagerPersonNumber, req.newManagerPersonNumber]),
        newManagerAssignmentNumber: newManagerAssignmentNumber
      });
    } else {
      skippedItems.push({
        managerType: mt,
        operation: 'SKIP',
        currentManager: rec.currentManager,
        currentManagerAssignmentNumber: rec.currentManagerAssignmentNumber,
        currentManagerPersonNumber: rec.currentManagerPersonNumber,
        reason: 'No existing Reward Manager record was found. This workflow updates Reward Manager only when a Reward Manager row already exists; it does not create a new Reward Manager row.'
      });
    }
  }
}

const firstUpdateItem = updateItems.length ? updateItems[0] : null;
const primaryExistingManagerPersonNumber = firstUpdateItem ? firstUpdateItem.currentManagerPersonNumber : null;
const primaryExistingManagerAssignmentNumber = firstUpdateItem ? firstUpdateItem.currentManagerAssignmentNumber : null;

const result = {
  hasError: errors.length > 0,
  inputSource: firstNonBlank([req.inputSource, 'MANUAL']),
  sourceFileName: firstNonBlank([req.sourceFileName, null]),
  sourceSheetName: firstNonBlank([req.sourceSheetName, null]),
  sourceRowNumber: firstNonBlank([req.sourceRowNumber, null]),
  sourceRecordCount: firstNonBlank([req.sourceRecordCount, null]),
  errors: errors,
  warnings: warnings,
  request: req,
  lookupEffectiveDate: lookupDate,
  updateEffectiveDate: updateDate,
  workersUniqID: workersUniqID,
  rawWorkersUniqID: rawWorkersUniqID,
  workersUniqIDSource: workerKeyResolution.source,
  periodOfServiceId: periodOfServiceId,
  assignmentsUniqID: assignmentsUniqID,
  rawAssignmentsUniqID: rawAssignmentsUniqID,
  assignmentsUniqIDSource: assignmentKeyResolution.source,
  targetWorkerName: displayName(targetWorker),
  targetWorkerPersonNumber: firstNonBlank([resolvedTargetPersonNumber, req.workerPersonNumber]),
  targetAssignmentId: targetAssignmentId,
  targetAssignmentNumber: targetAssignmentNumber,
  newManagerName: displayName(newManagerWorker),
  newManagerPersonNumber: firstNonBlank([resolvedNewManagerPersonNumber, req.newManagerPersonNumber]),
  newManagerAssignmentId: newManagerAssignmentId,
  newManagerAssignmentNumber: newManagerAssignmentNumber,
  primaryExistingManagerPersonNumber: primaryExistingManagerPersonNumber,
  primaryExistingManagerAssignmentNumber: primaryExistingManagerAssignmentNumber,
  requestedManagerTypes: requestedManagerTypes,
  managerTypes: updateItems.map(item => item.managerType),
  managerRecords: managerRecords,
  payloads: payloads,
  updateItems: updateItems,
  skippedItems: skippedItems,
  effectiveHeaderPatch: 'RangeMode=UPDATE;RangeStartDate=' + updateDate + ';RangeEndDate=4712-12-31',
  effectiveHeaderCreate: 'RangeStartDate=' + updateDate + ';RangeEndDate=4712-12-31'
};

return result;

const errors = $context.$nodes.BUILD_MANAGER_UPDATE_CONTEXT.$output.result.errors || [];
let message = 'I could not prepare the manager update because:<br><ul>' + errors.map(e => '<li>' + e + '</li>').join('') + '</ul>';
return { message };

const ctx = $context.$nodes.BUILD_MANAGER_UPDATE_CONTEXT.$output.result;
const req = ctx.request || {};
const currentMgrResponse = ($context.$nodes.GET_CURRENT_MANAGER && $context.$nodes.GET_CURRENT_MANAGER.$output) || {};

const firstNonBlank = (vals) => {
  for (let i = 0; i < vals.length; i++) {
    const v = vals[i];
    if (v !== null && v !== undefined && String(v).trim() !== '') return v;
  }
  return null;
};

const asString = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const upper = (v) => asString(v).toUpperCase();

const escapeHtml = (v) => {
  return asString(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

const itemsOf = (response) => {
  if (!response) return [];
  if (Array.isArray(response.items)) return response.items;
  if (Array.isArray(response.Items)) return response.Items;
  return [];
};

const childItems = (obj, prop) => {
  if (!obj) return [];
  const v = obj[prop];
  if (Array.isArray(v)) return v;
  if (v && Array.isArray(v.items)) return v.items;
  if (v && Array.isArray(v.Items)) return v.Items;
  return [];
};

const displayNameFromNameItem = (n) => {
  if (!n) return null;
  return firstNonBlank([
    n.FullName,
    n.DisplayName,
    n.ListName,
    n.Name,
    (firstNonBlank([n.FirstName, n.GivenName]) && firstNonBlank([n.LastName, n.FamilyName])) ? (firstNonBlank([n.FirstName, n.GivenName]) + ' ' + firstNonBlank([n.LastName, n.FamilyName])) : null
  ]);
};

const displayName = (person) => {
  if (!person) return null;
  const names = childItems(person, 'names');
  let primaryName = null;
  let globalName = null;
  let anyName = null;
  for (let i = 0; i < names.length; i++) {
    const n = names[i] || {};
    const dn = displayNameFromNameItem(n);
    if (!dn) continue;
    if (!anyName) anyName = dn;
    if (!primaryName && (n.PrimaryFlag === true || upper(n.PrimaryFlag) === 'TRUE' || upper(n.PrimaryFlag) === 'Y')) primaryName = dn;
    if (!globalName && (upper(n.NameType) === 'GLOBAL' || upper(n.NameType) === 'GLOBAL_NAME')) globalName = dn;
  }
  return firstNonBlank([
    person.DisplayName,
    person.displayName,
    person.PersonDisplayName,
    person.FullName,
    person.Name,
    person.PersonName,
    primaryName,
    globalName,
    anyName,
    person.PersonNumber
  ]);
};

const currentMgrItems = itemsOf(currentMgrResponse);
const currentMgrWorker = currentMgrItems.length ? currentMgrItems[0] : null;
const currentMgrLookupName = displayName(currentMgrWorker);
const currentMgrLookupPersonNumber = currentMgrWorker ? firstNonBlank([currentMgrWorker.PersonNumber, currentMgrWorker.personNumber]) : null;

const formatPerson = (name, personNumber, assignmentNumber) => {
  const n = asString(name);
  const pn = asString(personNumber);
  const an = asString(assignmentNumber);
  let label = n;
  if (!label || label === pn || label === an) label = 'Name not available';
  let out = `<b>${escapeHtml(label)}</b>`;
  if (pn) out += ` | Person Number: ${escapeHtml(pn)}`;
  if (an) out += ` | Assignment: ${escapeHtml(an)}`;
  return out;
};

const proposedManagerDisplayForItem = (item) => {
  return formatPerson(ctx.newManagerName || item.newManager, item.newManagerPersonNumber || ctx.newManagerPersonNumber, item.newManagerAssignmentNumber || ctx.newManagerAssignmentNumber);
};

const currentManagerDisplayForItem = (item) => {
  const itemPersonNumber = asString(item.currentManagerPersonNumber);
  let name = null;
  if (currentMgrLookupName && itemPersonNumber && asString(currentMgrLookupPersonNumber) === itemPersonNumber) name = currentMgrLookupName;
  if (!name) name = item.currentManager;
  return formatPerson(name, item.currentManagerPersonNumber, item.currentManagerAssignmentNumber);
};

const itemForType = (managerType) => {
  const items = ctx.updateItems || [];
  for (let i = 0; i < items.length; i++) {
    if (upper(items[i].managerType) === managerType) return items[i];
  }
  return null;
};

const skippedForType = (managerType) => {
  const items = ctx.skippedItems || [];
  for (let i = 0; i < items.length; i++) {
    if (upper(items[i].managerType) === managerType) return items[i];
  }
  return null;
};

const rangeText = (item) => {
  const start = item && item.currentEffectiveStartDate ? item.currentEffectiveStartDate : 'Not available';
  const end = item && item.currentEffectiveEndDate ? item.currentEffectiveEndDate : 'Not available';
  return `${escapeHtml(start)} to ${escapeHtml(end)}`;
};

const changeTypeLabel = req.updateType === 'LINE_MANAGER'
  ? 'Line Manager update'
  : 'Time Card Manager update';

const sourceLabel = ctx.inputSource === 'FILE' ? 'Uploaded file' : 'Manual chat input';

let msg = `<b>Confirm Manager Update</b><br><br>`;

msg += `<b>Request Summary</b><br>`;
msg += `<ul>`;
msg += `<li><b>Source</b>: ${escapeHtml(sourceLabel)}</li>`;
if (ctx.inputSource === 'FILE') {
  if (ctx.sourceFileName) msg += `<li><b>File</b>: ${escapeHtml(ctx.sourceFileName)}</li>`;
  if (ctx.sourceSheetName) msg += `<li><b>Sheet</b>: ${escapeHtml(ctx.sourceSheetName)}</li>`;
  if (ctx.sourceRowNumber) msg += `<li><b>Excel Row</b>: ${escapeHtml(ctx.sourceRowNumber)}</li>`;
}
msg += `<li><b>Requested Change</b>: ${escapeHtml(changeTypeLabel)}</li>`;
msg += `<li><b>Employee</b>: ${formatPerson(ctx.targetWorkerName, ctx.targetWorkerPersonNumber, ctx.targetAssignmentNumber)}</li>`;
msg += `<li><b>Proposed Manager</b>: ${formatPerson(ctx.newManagerName, ctx.newManagerPersonNumber, ctx.newManagerAssignmentNumber)}</li>`;
msg += `<li><b>Effective Date</b>: ${escapeHtml(req.effectiveDate)}</li>`;
if (req.reasonCode) msg += `<li><b>Reason Code</b>: ${escapeHtml(req.reasonCode)}</li>`;
msg += `</ul>`;

const addUpdateSection = (title, managerType) => {
  const item = itemForType(managerType);
  const skipped = skippedForType(managerType);
  msg += `<b>${escapeHtml(title)}</b><br>`;
  msg += `<ul>`;
  if (item) {
    msg += `<li><b>Action</b>: ${escapeHtml(item.operation)}</li>`;
    msg += `<li><b>Existing Manager</b>: ${currentManagerDisplayForItem(item)}</li>`;
    msg += `<li><b>Proposed Manager</b>: ${proposedManagerDisplayForItem(item)}</li>`;
    msg += `<li><b>Existing Manager Date Range</b>: ${rangeText(item)}</li>`;
    msg += `<li><b>Change Effective From</b>: ${escapeHtml(req.effectiveDate)}</li>`;
  } else if (skipped) {
    msg += `<li><b>Action</b>: No update will be performed</li>`;
    msg += `<li><b>Reason</b>: ${escapeHtml(skipped.reason)}</li>`;
  } else {
    msg += `<li>No ${escapeHtml(title)} record is prepared for this request.</li>`;
  }
  msg += `</ul>`;
};

if (req.updateType === 'LINE_MANAGER') {
  addUpdateSection('Line Manager Update Details', 'LINE_MANAGER');
  addUpdateSection('Reward Manager Update Details', 'HS2_HS2_REWARD_MANAGER');
} else {
  addUpdateSection('Time Card Manager Update Details', 'HS2_TIMECARD_MANAGER');
}

msg += `<b>Approval Action</b><br>`;
msg += `Click <b>Approve</b> to submit this manager update to Oracle HCM. Click <b>Reject</b> to cancel without making any change.`;

return { message: msg };

