if (ctx.hasError === true && Array.isArray(ctx.errors)) { for (var i=0;i<ctx.errors.length;i++) hard.push(ctx.errors[i]); }
var workerPN = asString(ctx.targetWorkerPersonNumber);
var newMgrPN = asString(ctx.newManagerPersonNumber);
if (workerPN && newMgrPN && workerPN === newMgrPN) hard.push('A worker cannot be their own manager. The proposed manager is the same person as the worker.');
var workerAsgNum = asString(ctx.targetAssignmentNumber);
var newMgrAsgNum = asString(ctx.newManagerAssignmentNumber);
if (workerAsgNum && newMgrAsgNum && workerAsgNum === newMgrAsgNum) hard.push('The proposed manager assignment is the same as the worker assignment, which would create a direct reporting cycle.');
var eff = asString(req.effectiveDate);
if (!eff) {
  hard.push('An effective date is required.');
} else {
  var d = new Date(eff + 'T00:00:00Z');
  var t = new Date(today + 'T00:00:00Z');
  if (isFinite(d.getTime()) && isFinite(t.getTime())) {
    var diffDays = Math.round((t.getTime() - d.getTime()) / 86400000);
    if (diffDays > 30) hard.push('The effective date ' + eff + ' is more than 30 days in the past. Choose a date within the last 30 days or a future date.');
  }
}
if (!newMgrAsgNum) hard.push('The proposed manager could not be resolved to an active assignment.');
var items = Array.isArray(ctx.updateItems) ? ctx.updateItems : [];
for (var k=0;k<items.length;k++){
  var it = items[k] || new Object();
  if (asString(it.currentManagerAssignmentNumber) && asString(it.currentManagerAssignmentNumber) === newMgrAsgNum) {
