vout.hardFailures = hard;
vout.softWarnings = soft;
vout.workerName = ctx.targetWorkerName || null;
vout.newManagerName = ctx.newManagerName || null;
vout.effectiveDate = req.effectiveDate || null;
vout.confirmCommand = confirmCommand;
var targetType = asString(req.updateType || 'LINE_MANAGER').toUpperCase();
var currentName = '';
for (var ci = 0; ci < items.length; ci++) {
  var cit = items[ci] || new Object();
  if (targetType && asString(cit.managerType).toUpperCase() !== targetType) continue;
  currentName = asString(cit.currentManager) || asString(cit.currentManagerAssignmentNumber);
  if (currentName) break;
}
if (!currentName && items.length) currentName = asString(items[0].currentManager) || asString(items[0].currentManagerAssignmentNumber);
var managerLabel = targetType === 'HS2_TIMECARD_MANAGER' ? 'Time Card Manager' : 'Line Manager';
var ccard = new Object();
ccard.title = 'Confirm Manager Update';
ccard.patternId = 'cardWidget';
ccard.description = 'Review the proposed change before it is written.';
