csum = csum + NL + managerLabel + ': ' + (currentName || 'Not currently assigned') + ' ' + ARROW + ' ' + (asString(ctx.newManagerName) || 'Proposed manager');
csum = csum + NL + 'Effective Date: ' + (asString(req.effectiveDate) || 'Not set');
for (var si = 0; si < soft.length; si++) csum = csum + NL + 'Caution: ' + soft[si];
cp.summary = csum;
cp.badgeText = 'Needs confirmation';
cp.variant = 'warning';
var link = new Object();
link.text = 'Confirm Change';
link.action = confirmCommand;
cp.link = link;
ccard.properties = cp;
vout.confirmCard = ccard;
return vout;

